/**
 * SRA Regulatory Boundary Guardrail
 * Enforces Legal Services Act 2007 and Section 203(3) Employment Rights Act 1996 compliance.
 * Guarantees zero unauthorized practice of law by framing all AI intelligence as an objective statutory audit.
 */

export const SRA_COMPLIANCE_DISCLAIMER = 
  'This pre-flight case audit and statutory evaluation is generated by SettlementCheck strictly for objective information and triage purposes. It does not constitute formal legal advice or create a solicitor-client relationship. Under Section 203(3) of the Employment Rights Act 1996, formal statutory advice must be delivered by your instructed independent SRA-regulated solicitor.';

const FORBIDDEN_REPLACEMENTS: Array<[RegExp, string]> = [
  [/\bwe advise you to\b/gi, 'the statutory analysis indicates you should consider'],
  [/\bour legal advice is\b/gi, 'the objective statutory evaluation shows'],
  [/\bas your solicitor\b/gi, 'for your instructed solicitor'],
  [/\bas your legal representative\b/gi, 'for your independent legal adviser'],
  [/\bI advise you to\b/gi, 'the statutory analysis suggests'],
  [/\bthis legal advice confirms\b/gi, 'this statutory audit confirms'],
];

export function sanitizeAdvicePhrasing(text: string): string {
  let sanitized = text;
  for (const [regex, replacement] of FORBIDDEN_REPLACEMENTS) {
    if (regex.test(sanitized)) {
      sanitized = sanitized.replace(regex, replacement);
    }
  }
  return sanitized;
}

export function enforceSraRegulatoryBoundary(text: string): { sanitizedText: string; isModified: boolean } {
  let sanitized = sanitizeAdvicePhrasing(text);
  let isModified = sanitized !== text;

  // Ensure disclaimer presence if it's a long report
  if (!sanitized.includes('Section 203(3)') && sanitized.length > 200) {
    sanitized += `\n\n---\n**SRA Regulatory Notice**: ${SRA_COMPLIANCE_DISCLAIMER}`;
    isModified = true;
  }

  return {
    sanitizedText: sanitized,
    isModified,
  };
}
